#!/usr/bin/env node

'use strict';

const chalk = require('chalk');
const path = require('path');
const fs = require('fs');
const { execSync } = require('child_process');

const LOGO = `
  ___                _   _      
 / __|_ _ _____ __ _| | | |_ __ 
| (__| '_/ -_) V  V / |_| | '_ \\
 \\___|_| \\___|\\_/\\_/ \\___/| .__/
                          |_|   
`;

const CONFIG_FILE = 'crewup.config.json';
const GENERATED_HEADER = '<!-- Generated by CrewUp -->';

// ============ Config Loading & Validation ============

function loadConfig(configPath) {
  if (!fs.existsSync(configPath)) {
    console.log(chalk.red(`No ${CONFIG_FILE} found. Run "crewup init" first.\n`));
    process.exit(1);
  }

  let raw;
  try {
    raw = fs.readFileSync(configPath, 'utf-8');
  } catch (err) {
    console.log(chalk.red(`Cannot read ${CONFIG_FILE}: ${err.message}\n`));
    process.exit(1);
  }

  let config;
  try {
    config = JSON.parse(raw);
  } catch (err) {
    console.log(chalk.red(`Invalid JSON in ${CONFIG_FILE}:\n`));
    console.log(chalk.yellow(`  ${err.message}\n`));
    console.log(chalk.gray('Fix the JSON syntax and try again.\n'));
    process.exit(1);
  }

  const errors = validateConfig(config);
  if (errors.length > 0) {
    console.log(chalk.red(`Invalid configuration in ${CONFIG_FILE}:\n`));
    for (const err of errors) {
      console.log(chalk.red(`  - ${err}`));
    }
    console.log(chalk.gray('\nFix the config and try again, or run "crewup init" to regenerate.\n'));
    process.exit(1);
  }

  return config;
}

function validateConfig(config) {
  const errors = [];

  if (!config.project) {
    errors.push('Missing "project" section');
  } else {
    if (!config.project.name) errors.push('Missing "project.name"');
    if (!Array.isArray(config.project.repos) || config.project.repos.length === 0) {
      errors.push('Missing or empty "project.repos" array');
    } else {
      for (let i = 0; i < config.project.repos.length; i++) {
        if (!config.project.repos[i].name) errors.push(`Missing "project.repos[${i}].name"`);
      }
    }
  }

  if (!config.agents) {
    errors.push('Missing "agents" section');
  } else {
    if (!Array.isArray(config.agents.developers)) {
      errors.push('Missing "agents.developers" array');
    } else if (config.agents.developers.length === 0) {
      errors.push('"agents.developers" is empty — at least 1 developer is required');
    }
  }

  if (!config.models) {
    errors.push('Missing "models" section');
  } else {
    if (!config.models.developer && !config.models.default) errors.push('Missing "models.developer"');
    if (!config.models.small) errors.push('Missing "models.small"');
    if (!config.models.escalation) errors.push('Missing "models.escalation"');
    if (!config.models.orchestrator && !config.models.escalation) errors.push('Missing "models.orchestrator"');
  }

  if (!config.techStack) {
    errors.push('Missing "techStack" section');
  }

  if (!Array.isArray(config.mcpServers)) {
    errors.push('Missing or invalid "mcpServers" — must be an array');
  }

  return errors;
}

/** Extract positional args (filter out flags) */
function positionalArgs(args) {
  return args.filter(a => !a.startsWith('-'));
}

// ============ Main ============

async function main() {
  const args = process.argv.slice(2);

  // Flags that skip the logo
  if (args.includes('--version') || args.includes('-v')) {
    const pkg = require('./package.json');
    console.log(`crewup v${pkg.version}`);
    return;
  }

  console.log(chalk.cyan(LOGO));
  console.log(chalk.gray('  AI Development Team Orchestration\n'));

  if (args.includes('--help') || args.includes('-h')) {
    printHelp();
    return;
  }

  const posArgs = positionalArgs(args);
  const command = posArgs[0];
  const dryRun = args.includes('--dry-run');

  switch (command) {
    case 'init':
      await runInit(dryRun);
      break;

    case 'apply':
      await runApply(dryRun);
      break;

    case 'add-agent':
      await runAddAgent(posArgs[1]);
      break;

    case 'remove-agent':
      await runRemoveAgent(posArgs[1]);
      break;

    case 'doctor':
      await runDoctor();
      break;

    case 'estimate':
      await runEstimate(posArgs.slice(1).join(' '));
      break;

    case 'upgrade':
      await runUpgrade();
      break;

    case 'status':
      runStatus();
      break;

    case 'undo':
      await runUndo();
      break;

    case 'stats':
      runStats();
      break;

    case 'run':
      await runTask(args);
      break;

    case 'templates':
      runTemplatesList();
      break;

    case 'ui':
      runUI(args);
      break;

    default:
      printHelp();
      break;
  }
}

// ============ Commands ============

async function runInit(dryRun) {
  const configPath = path.join(process.cwd(), CONFIG_FILE);

  if (fs.existsSync(configPath)) {
    const inquirer = (await import('inquirer')).default;
    const { overwrite } = await inquirer.prompt([{
      type: 'confirm',
      name: 'overwrite',
      message: `${CONFIG_FILE} already exists. Re-run wizard and overwrite?`,
      default: false
    }]);
    if (!overwrite) {
      console.log(chalk.yellow(`\nUse "crewup apply" to regenerate files from existing config.\n`));
      return;
    }
  }

  console.log(chalk.green.bold('  Starting CrewUp Setup Wizard\n'));

  const { runWizard } = require('./wizard');
  const config = await runWizard();

  if (dryRun) {
    console.log(chalk.cyan.bold('\n── Dry Run ── (no files written)\n'));
    console.log(chalk.gray('Config that would be saved:\n'));
    console.log(JSON.stringify(config, null, 2));
    console.log(chalk.cyan('\nFiles that would be generated:\n'));
    const { generate } = require('./generator');
    generate(config, process.cwd(), { dryRun: true });
    return;
  }

  // Save config
  fs.writeFileSync(configPath, JSON.stringify(config, null, 2));
  console.log(chalk.green(`\n✓ Configuration saved to ${CONFIG_FILE}`));

  // Generate files
  const { generate } = require('./generator');
  generate(config, process.cwd());

  console.log(chalk.green.bold('\n========================================'));
  console.log(chalk.green.bold('  CrewUp Setup Complete!'));
  console.log(chalk.green.bold('========================================\n'));
  console.log('Your AI development team is configured at .opencode/\n');
  console.log('Next steps:');
  console.log(`  1. Review ${CONFIG_FILE} and tweak if needed`);
  console.log('  2. Run ' + chalk.cyan('crewup apply') + ' to regenerate after edits');
  console.log('  3. Run ' + chalk.cyan('crewup doctor') + ' to verify setup');
  console.log('  4. Start OpenCode: ' + chalk.cyan('opencode'));
  console.log('');
}

async function runApply(dryRun) {
  const configPath = path.join(process.cwd(), CONFIG_FILE);
  const config = loadConfig(configPath);
  const { generate } = require('./generator');

  // Re-detect coding patterns if missing (older configs)
  if (!config.codingPatterns) {
    const { detect } = require('./detector');
    const detected = detect(process.cwd());
    config.codingPatterns = detected.codingPatterns || {};
  }

  if (dryRun) {
    console.log(chalk.cyan.bold('── Dry Run ── (no files written)\n'));
    generate(config, process.cwd(), { dryRun: true });
    return;
  }

  generate(config, process.cwd());
  console.log(chalk.green(`\n✓ All files regenerated from ${CONFIG_FILE}\n`));
}

async function runAddAgent(name) {
  const configPath = path.join(process.cwd(), CONFIG_FILE);
  const config = loadConfig(configPath);
  const inquirer = (await import('inquirer')).default;

  const answers = await inquirer.prompt([
    {
      type: 'input',
      name: 'name',
      message: 'Developer name:',
      default: name || undefined,
      validate: v => {
        if (!v) return 'Name is required';
        const existing = config.agents.developers.find(
          d => d.name.toLowerCase() === v.toLowerCase()
        );
        if (existing) return `Agent "${existing.name}" already exists. Choose a different name.`;
        return true;
      }
    },
    {
      type: 'list',
      name: 'specialty',
      message: 'Primary specialty:',
      choices: ['fullstack', 'frontend', 'backend', 'devops', 'data']
    },
    {
      type: 'input',
      name: 'color',
      message: 'Agent color (hex):',
      default: '#' + Math.floor(Math.random() * 16777215).toString(16).padStart(6, '0'),
      validate: v => /^#[0-9a-fA-F]{6}$/.test(v) ? true : 'Enter a valid hex color (e.g. #1A936F)'
    }
  ]);

  config.agents.developers.push({
    name: answers.name,
    specialty: answers.specialty,
    color: answers.color
  });

  fs.writeFileSync(configPath, JSON.stringify(config, null, 2));

  const { generate } = require('./generator');
  generate(config, process.cwd());

  console.log(chalk.green(`\n✓ Added developer "${answers.name}" and regenerated agent files.\n`));
}

async function runRemoveAgent(name) {
  const configPath = path.join(process.cwd(), CONFIG_FILE);
  const config = loadConfig(configPath);
  const inquirer = (await import('inquirer')).default;

  if (config.agents.developers.length <= 1) {
    console.log(chalk.red('Cannot remove — at least 1 developer agent is required.\n'));
    return;
  }

  let targetName = name;
  if (!targetName) {
    const { selected } = await inquirer.prompt([{
      type: 'list',
      name: 'selected',
      message: 'Which developer agent to remove?',
      choices: config.agents.developers.map(d => ({ name: `${d.name} (${d.specialty})`, value: d.name }))
    }]);
    targetName = selected;
  }

  const idx = config.agents.developers.findIndex(d => d.name.toLowerCase() === targetName.toLowerCase());
  if (idx === -1) {
    console.log(chalk.red(`Agent "${targetName}" not found.\n`));
    console.log('Available agents: ' + config.agents.developers.map(d => d.name).join(', '));
    return;
  }

  const removed = config.agents.developers.splice(idx, 1)[0];
  fs.writeFileSync(configPath, JSON.stringify(config, null, 2));

  const { generate } = require('./generator');
  generate(config, process.cwd());

  console.log(chalk.green(`\n✓ Removed developer "${removed.name}" and regenerated agent files.\n`));
}

// ============ Doctor ============

async function runDoctor() {
  const checks = [];

  function check(name, fn) {
    try {
      const result = fn();
      checks.push({ name, ...result });
    } catch (err) {
      checks.push({ name, ok: false, detail: err.message });
    }
  }

  console.log(chalk.bold('  Running health checks...\n'));

  // 1. Node.js version
  check('Node.js', () => {
    const ver = process.version;
    const major = parseInt(ver.slice(1).split('.')[0], 10);
    return { ok: major >= 18, detail: ver, warn: major < 18 ? 'Requires Node.js >= 18' : null };
  });

  // 2. Git
  check('Git', () => {
    try {
      const ver = execSync('git --version', { encoding: 'utf-8', stdio: ['pipe', 'pipe', 'pipe'] }).trim();
      return { ok: true, detail: ver.replace('git version ', 'v') };
    } catch {
      return { ok: false, detail: 'Not found — install git' };
    }
  });

  // 3. OpenCode
  check('OpenCode', () => {
    try {
      const ver = execSync('opencode --version', { encoding: 'utf-8', timeout: 5000, stdio: ['pipe', 'pipe', 'pipe'] }).trim();
      return { ok: true, detail: `v${ver}` };
    } catch {
      return { ok: false, detail: 'Not found — install from https://opencode.ai' };
    }
  });

  // 4. Config file
  const configPath = path.join(process.cwd(), CONFIG_FILE);
  check('Config file', () => {
    if (!fs.existsSync(configPath)) {
      return { ok: false, detail: `${CONFIG_FILE} not found — run "crewup init"` };
    }
    try {
      const raw = fs.readFileSync(configPath, 'utf-8');
      const config = JSON.parse(raw);
      const errors = validateConfig(config);
      if (errors.length > 0) {
        return { ok: false, detail: `${errors.length} validation error(s): ${errors[0]}` };
      }
      const repoCount = config.project.repos.length;
      const agentCount = config.agents.developers.length;
      return { ok: true, detail: `Valid (${repoCount} repos, ${agentCount} developers)` };
    } catch (err) {
      return { ok: false, detail: `Parse error: ${err.message}` };
    }
  });

  // 5. Config version
  check('Config version', () => {
    if (!fs.existsSync(configPath)) return { ok: false, detail: 'No config' };
    const config = JSON.parse(fs.readFileSync(configPath, 'utf-8'));
    const { CURRENT_VERSION } = require('./migrator');
    const ver = config.version || 0;
    if (ver < CURRENT_VERSION) {
      return { ok: false, detail: `v${ver} — run "crewup upgrade" to migrate to v${CURRENT_VERSION}`, warn: true };
    }
    return { ok: true, detail: `v${ver} (current)` };
  });

  // 6. Generated files
  check('Generated files', () => {
    if (!fs.existsSync(configPath)) return { ok: false, detail: 'No config' };
    const config = JSON.parse(fs.readFileSync(configPath, 'utf-8'));
    const { getExpectedFiles } = require('./generator');
    const expected = getExpectedFiles(config);
    const missing = expected.filter(f => !fs.existsSync(path.join(process.cwd(), f)));
    if (missing.length > 0) {
      return { ok: false, detail: `${expected.length - missing.length}/${expected.length} present — run "crewup apply"` };
    }
    return { ok: true, detail: `${expected.length}/${expected.length} present` };
  });

  // 7. Files freshness
  check('Files up-to-date', () => {
    if (!fs.existsSync(configPath)) return { ok: false, detail: 'No config' };
    const configMtime = fs.statSync(configPath).mtimeMs;
    const config = JSON.parse(fs.readFileSync(configPath, 'utf-8'));
    const { getExpectedFiles } = require('./generator');
    const expected = getExpectedFiles(config);
    let staleCount = 0;
    for (const f of expected) {
      const fullPath = path.join(process.cwd(), f);
      if (fs.existsSync(fullPath)) {
        if (fs.statSync(fullPath).mtimeMs < configMtime) staleCount++;
      }
    }
    if (staleCount > 0) {
      return { ok: false, detail: `${staleCount} file(s) older than config — run "crewup apply"`, warn: true };
    }
    return { ok: true, detail: 'All current' };
  });

  // 8. Git repo
  check('Git repository', () => {
    try {
      const branch = execSync('git rev-parse --abbrev-ref HEAD', { encoding: 'utf-8', stdio: ['pipe', 'pipe', 'pipe'] }).trim();
      return { ok: true, detail: `Branch: ${branch}` };
    } catch {
      return { ok: false, detail: 'Not a git repository', warn: true };
    }
  });

  // 9. MCP servers (check binaries)
  if (fs.existsSync(configPath)) {
    try {
      const config = JSON.parse(fs.readFileSync(configPath, 'utf-8'));
      for (const server of (config.mcpServers || [])) {
        check(`MCP: ${server}`, () => {
          // Check if npx can resolve the package (just verify node_modules or global)
          const knownPackages = {
            'playwright': '@playwright/mcp',
            'memory': '@modelcontextprotocol/server-memory',
            'sequential-thinking': '@modelcontextprotocol/server-sequential-thinking',
            'azure-devops': '@azure-devops/mcp',
            'github-mcp': '@modelcontextprotocol/server-github',
            'teams-mcp': '@floriscornel/teams-mcp',
          };
          const pkg = knownPackages[server];
          if (!pkg) return { ok: true, detail: 'Unknown package — skipped' };
          // We can't easily check if npx packages are available without running them,
          // so just report as info
          return { ok: true, detail: `Will use npx (${pkg})` };
        });
      }
    } catch (_) {}
  }

  // Print results
  console.log(chalk.bold('  Doctor Report\n'));
  let issueCount = 0;
  let warnCount = 0;

  for (const c of checks) {
    const icon = c.ok ? chalk.green('✓') : (c.warn ? chalk.yellow('!') : chalk.red('✗'));
    const detail = c.ok ? chalk.gray(c.detail) : (c.warn ? chalk.yellow(c.detail) : chalk.red(c.detail));
    console.log(`  ${icon} ${chalk.bold(c.name.padEnd(20))} ${detail}`);
    if (!c.ok && !c.warn) issueCount++;
    if (c.warn) warnCount++;
  }

