// ============ Estimate ============

async function runEstimate(description) {
  const configPath = path.join(process.cwd(), CONFIG_FILE);
  const config = loadConfig(configPath);

  if (!description) {
    const inquirer = (await import('inquirer')).default;
    const ans = await inquirer.prompt([{
      type: 'input',
      name: 'description',
      message: 'Describe the story/task to estimate:',
      validate: v => v ? true : 'Description is required',
    }]);
    description = ans.description;
  }

  const { estimate } = require('./estimator');
  const result = estimate(description, config);

  // Display
  console.log(chalk.bold(`  Cost Estimate\n`));
  console.log(`  Task: ${chalk.white(result.description)}`);
  console.log(`  Complexity: ${chalk.bold(result.complexity.label)} (${result.complexity.score}x)\n`);

  // Table header
  const nameW = 22, modelW = 28, tokenW = 14, costW = 10;
  console.log(
    '  ' +
    chalk.gray('Agent'.padEnd(nameW)) +
    chalk.gray('Model'.padEnd(modelW)) +
    chalk.gray('Est. Tokens'.padEnd(tokenW)) +
    chalk.gray('Est. Cost'.padEnd(costW))
  );
  console.log('  ' + chalk.gray('─'.repeat(nameW + modelW + tokenW + costW)));

  for (const agent of result.agents) {
    const tokens = agent.inputTokens + agent.outputTokens;
    const tokenStr = formatTokens(tokens);
    const costStr = `$${agent.cost.toFixed(2)}`;
    const modelShort = agent.model.split('/').pop();
    console.log(
      '  ' +
      chalk.white(agent.name.padEnd(nameW)) +
      chalk.gray(modelShort.padEnd(modelW)) +
      chalk.cyan(tokenStr.padEnd(tokenW)) +
      chalk.green(costStr.padEnd(costW)) +
      (agent.note ? chalk.gray(` ${agent.note}`) : '')
    );
  }

  console.log('  ' + chalk.gray('─'.repeat(nameW + modelW + tokenW + costW)));
  console.log(
    '  ' +
    chalk.bold('Total'.padEnd(nameW)) +
    ''.padEnd(modelW) +
    chalk.cyan.bold(formatTokens(result.totals.totalTokens).padEnd(tokenW)) +
    chalk.green.bold(`$${result.totals.estimatedCost.toFixed(2)}`.padEnd(costW))
  );

  console.log('');
  console.log(chalk.gray(`  Worst case (retries + escalation): $${result.totals.worstCaseCost.toFixed(2)}`));
  console.log(chalk.gray(`  Note: Actual cost varies. Complex tasks with test failures cost more.`));
  console.log('');
}

function formatTokens(n) {
  if (n >= 1_000_000) return `~${(n / 1_000_000).toFixed(1)}M`;
  if (n >= 1_000) return `~${(n / 1_000).toFixed(0)}K`;
  return `~${n}`;
}

// ============ Upgrade ============

async function runUpgrade() {
  const configPath = path.join(process.cwd(), CONFIG_FILE);

  if (!fs.existsSync(configPath)) {
    console.log(chalk.red(`No ${CONFIG_FILE} found. Run "crewup init" first.\n`));
    return;
  }

  let raw;
  try {
    raw = fs.readFileSync(configPath, 'utf-8');
  } catch (err) {
    console.log(chalk.red(`Cannot read ${CONFIG_FILE}: ${err.message}\n`));
    return;
  }

  let config;
  try {
    config = JSON.parse(raw);
  } catch (err) {
    console.log(chalk.red(`Invalid JSON in ${CONFIG_FILE}: ${err.message}\n`));
    return;
  }

  const { migrate, CURRENT_VERSION } = require('./migrator');
  const { config: migrated, migrated: wasMigrated, fromVersion, toVersion } = migrate(config);

  if (!wasMigrated) {
    console.log(chalk.green(`  Config is already at version ${CURRENT_VERSION}. No migration needed.\n`));

    // Still regenerate files in case templates have been updated
    const { generate } = require('./generator');
    generate(migrated, process.cwd());
    console.log(chalk.green(`\n✓ Agent files regenerated with latest templates.\n`));
    return;
  }

  console.log(chalk.cyan(`  Migrating config: v${fromVersion} → v${toVersion}\n`));

  // Show what changed
  const newRaw = JSON.stringify(migrated, null, 2);
  const oldKeys = new Set(Object.keys(JSON.parse(raw)));
  const newKeys = new Set(Object.keys(migrated));
  const added = [...newKeys].filter(k => !oldKeys.has(k));
  const removed = [...oldKeys].filter(k => !newKeys.has(k));

  if (added.length > 0) console.log(chalk.green(`  Added fields: ${added.join(', ')}`));
  if (removed.length > 0) console.log(chalk.yellow(`  Removed fields: ${removed.join(', ')}`));

  // Save migrated config
  fs.writeFileSync(configPath, newRaw);
  console.log(chalk.green(`\n  ✓ Config migrated and saved`));

  // Regenerate
  const { generate } = require('./generator');
  generate(migrated, process.cwd());
  console.log(chalk.green(`\n✓ Upgrade complete. Config v${fromVersion} → v${toVersion}, all files regenerated.\n`));
}

// ============ Status ============

function runStatus() {
  const configPath = path.join(process.cwd(), CONFIG_FILE);
  const config = loadConfig(configPath);

  console.log(chalk.bold('Project: ') + config.project.name);
  console.log(chalk.bold('Provider: ') + (config.project.provider || 'none'));
  console.log(chalk.bold('Config version: ') + (config.version || 0));
  console.log(chalk.bold('Tech Stack: ') + (config.techStack.frontend || 'none') + ' + ' + (config.techStack.backend || 'none'));
