async function runTask(args) {
  const templateId = getFlag(args, '--template');

  if (!templateId) {
    console.log(chalk.red('\n  Missing --template flag.\n'));
    console.log(chalk.gray('  Usage: crewup run --template <template-id> --<var> <value>'));
    console.log(chalk.gray('  Run `crewup templates` to see available templates.\n'));
    return;
  }

  const { resolveTemplate, BUILT_IN, loadCustomTemplates } = require('./templates');
  const custom = loadCustomTemplates(process.cwd());
  const allTemplates = { ...BUILT_IN, ...custom };

  if (!allTemplates[templateId]) {
    console.log(chalk.red(`\n  Unknown template: "${templateId}"\n`));
    console.log(chalk.gray('  Run `crewup templates` to see available templates.\n'));
    return;
  }

  // Extract all --key value pairs as variables
  const variables = {};
  for (let i = 0; i < args.length; i++) {
    if (args[i].startsWith('--') && args[i] !== '--template' && args[i] !== '--dry-run') {
      const key = args[i].replace(/^--/, '');
      const val = args[i + 1] && !args[i + 1].startsWith('--') ? args[i + 1] : '';
      variables[key] = val;
      if (val) i++; // skip value
    }
  }

  const result = resolveTemplate(templateId, variables);

  if (!result) {
    console.log(chalk.red(`\n  Failed to resolve template "${templateId}".\n`));
    return;
  }

  if (result.error) {
    console.log(chalk.red(`\n  ${result.error}\n`));
    const tmpl = allTemplates[templateId];
    console.log(chalk.gray(`  Required variables: ${tmpl.variables.join(', ')}`));
    console.log(chalk.gray(`  Example: crewup run --template ${templateId} ${tmpl.variables.map(v => `--${v} "<value>"`).join(' ')}\n`));
    return;
  }

  console.log(chalk.bold('\n  ── Task from Template ──\n'));
  console.log(chalk.white(`  Template: ${result.name}`));
  console.log(chalk.gray('  ─'.repeat(30)));
  // Indent each line of description
  result.description.split('\n').forEach(line => {
    console.log(chalk.gray('  ' + line));
  });
  console.log(chalk.gray('  ─'.repeat(30)));
  console.log('');

  if (args.includes('--dry-run')) {
    console.log(chalk.yellow('  [dry-run] Would send this task to the orchestrator.\n'));
    return;
  }

  // Load config and check it exists
  const configPath = path.join(process.cwd(), CONFIG_FILE);
  if (!fs.existsSync(configPath)) {
    console.log(chalk.red('  No crewup.config.json found. Run `crewup init` first.\n'));
    return;
  }

  console.log(chalk.cyan('  To execute this task, copy the description above into your AI coding tool'));
  console.log(chalk.cyan('  (e.g., OpenCode, Cursor, Windsurf) and the orchestrator will handle it.\n'));

  // Write task to a temp file for easy pasting
  const taskDir = path.join(process.cwd(), '.opencode');
  if (!fs.existsSync(taskDir)) fs.mkdirSync(taskDir, { recursive: true });
  const taskFile = path.join(taskDir, 'current-task.md');
  fs.writeFileSync(taskFile, `# ${result.name}\n\n${result.description}\n`);
  console.log(chalk.green(`  ✓ Task saved to .opencode/current-task.md\n`));
}

function getFlag(args, flag) {
  const idx = args.indexOf(flag);
  if (idx === -1 || idx + 1 >= args.length) return null;
  return args[idx + 1];
}

