/**
 * List all available templates
 */
function listTemplates() {
  return Object.entries(BUILT_IN).map(([id, t]) => ({
    id,
    name: t.name,
    description: t.description,
    variables: t.variables,
  }));
}

/**
 * Resolve a template by ID, filling in variables
 * @param {string} templateId
 * @param {object} variables - key/value pairs for template variables
 * @returns {{ name: string, description: string } | null}
 */
function resolveTemplate(templateId, variables = {}) {
  const tmpl = BUILT_IN[templateId];
  if (!tmpl) return null;

  // Merge defaults
  const vars = { ...tmpl.defaults, ...variables };

  // Check required variables
  const missing = tmpl.variables.filter(v => !vars[v] && !tmpl.defaults[v]);
  if (missing.length > 0) {
    return { error: `Missing required variables: ${missing.join(', ')}` };
  }

  return {
    name: tmpl.name,
    description: tmpl.template(vars),
  };
}

/**
 * Load custom templates from .opencode/templates/ if they exist
 */
function loadCustomTemplates(workspaceRoot) {
  const customDir = path.join(workspaceRoot || process.cwd(), '.opencode', 'templates');
  if (!fs.existsSync(customDir)) return {};

  const custom = {};
  const files = fs.readdirSync(customDir).filter(f => f.endsWith('.json'));
  for (const file of files) {
    try {
      const data = JSON.parse(fs.readFileSync(path.join(customDir, file), 'utf-8'));
      const id = path.basename(file, '.json');
      custom[id] = {
        name: data.name || id,
        description: data.description || '',
        variables: data.variables || [],
        defaults: data.defaults || {},
        template: (vars) => {
          let text = data.template || '';
          for (const [k, v] of Object.entries(vars)) {
            text = text.replace(new RegExp(`\\$\\{${k}\\}`, 'g'), v);
          }
          return text;
        },
      };
    } catch (_) {
      // skip invalid templates
    }
  }
  return custom;
}

module.exports = { BUILT_IN, listTemplates, resolveTemplate, loadCustomTemplates };

'use strict';

const express = require('express');
const http = require('http');
const path = require('path');
const { WebSocketServer } = require('ws');
const { setupRoutes } = require('./routes');
const { setupAdoRoutes } = require('./routes/ado');
const { RunManager } = require('./run-manager');

function startServer(options = {}) {
  const port = options.port || 4040;
  const workspaceRoot = options.workspaceRoot || process.cwd();

  const app = express();
  const server = http.createServer(app);

  // WebSocket server
  const wss = new WebSocketServer({ server, path: '/ws' });

  // Middleware
  app.use(express.json({ limit: '5mb' }));
  app.use(express.urlencoded({ extended: true }));

  // CORS for dev mode
  app.use((req, res, next) => {
    res.header('Access-Control-Allow-Origin', '*');
    res.header('Access-Control-Allow-Methods', 'GET, POST, PUT, DELETE, OPTIONS');
    res.header('Access-Control-Allow-Headers', 'Content-Type');
    if (req.method === 'OPTIONS') return res.sendStatus(200);
    next();
  });

  // Run manager
  const runManager = new RunManager(workspaceRoot, wss);

  // API routes
  setupRoutes(app, workspaceRoot, runManager);
  setupAdoRoutes(app, workspaceRoot);

  // Serve static client build
  const clientDist = path.join(__dirname, '..', 'client', 'dist');
  app.use(express.static(clientDist));

  // SPA fallback
  app.get('*', (req, res) => {
    if (req.path.startsWith('/api/') || req.path.startsWith('/ws')) {
      return res.status(404).json({ error: 'Not found' });
    }
    res.sendFile(path.join(clientDist, 'index.html'));
  });

  // WebSocket connection handling
  wss.on('connection', (ws) => {
    // Sync all runs to new client
    runManager.syncClient(ws);

    ws.on('message', (data) => {
      try {
        const msg = JSON.parse(data.toString());
        runManager.handleClientMessage(ws, msg);
      } catch (_) {}
    });
  });

  server.listen(port, async () => {
    const url = `http://localhost:${port}`;
    console.log(`\n  CrewUp Dashboard running at: ${url}\n`);

    // Start opencode server in background
    try {
      const opencodeUrl = await runManager.startOpencode();
      console.log(`  opencode server: ${opencodeUrl}`);
    } catch (err) {
      console.log(`  [warn] Could not start opencode server: ${err.message}`);
      console.log(`  Runs will not work until opencode is available.`);
    }

    // Open browser
    try {
      const open = process.platform === 'darwin' ? 'open' :
                   process.platform === 'win32' ? 'start' : 'xdg-open';
      require('child_process').execSync(`${open} ${url}`, { stdio: 'ignore' });
    } catch (_) {}
  });

  // Cleanup on shutdown
  process.on('SIGINT', () => {
    runManager.destroy();
    process.exit(0);
  });
  process.on('SIGTERM', () => {
    runManager.destroy();
    process.exit(0);
  });

  return server;
}

module.exports = { startServer };

