const fs = require('fs');
const path = require('path');

function setupRoutes(app, workspaceRoot, runManager) {
  const configPath = path.join(workspaceRoot, 'crewup.config.json');
  const historyPath = path.join(workspaceRoot, '.opencode', 'history.json');
  const agentsDir = path.join(workspaceRoot, '.opencode', 'agents');

  function readHistory() {
    if (!fs.existsSync(historyPath)) return [];
    try {
      const parsed = JSON.parse(fs.readFileSync(historyPath, 'utf-8'));
      if (Array.isArray(parsed)) return parsed;
      if (parsed && typeof parsed === 'object' && parsed.id) return [parsed];
      return [];
    } catch (_) { return []; }
  }

  // ============ Config ============

  app.get('/api/config', (req, res) => {
    if (!fs.existsSync(configPath)) {
      return res.status(404).json({ error: 'No crewup.config.json found' });
    }
    try {
      const config = JSON.parse(fs.readFileSync(configPath, 'utf-8'));
      res.json(config);
    } catch (err) {
      res.status(500).json({ error: err.message });
    }
  });

  app.put('/api/config', (req, res) => {
    try {
      const config = req.body;
      fs.writeFileSync(configPath, JSON.stringify(config, null, 2));
      res.json({ success: true });
    } catch (err) {
      res.status(500).json({ error: err.message });
    }
  });

  app.post('/api/apply', (req, res) => {
    try {
      const config = JSON.parse(fs.readFileSync(configPath, 'utf-8'));
      const { detect } = require('../../detector');
      const { generate } = require('../../generator');

      // Re-detect patterns
      if (!config.codingPatterns) {
        const detected = detect(workspaceRoot);
        config.codingPatterns = detected.codingPatterns || {};
      }

      const dryRun = req.body.dryRun || false;
      generate(config, workspaceRoot, { dryRun });
      res.json({ success: true, dryRun });
    } catch (err) {
      res.status(500).json({ error: err.message });
    }
  });

  // ============ History ============

  app.get('/api/history', (req, res) => {
    res.json(readHistory());
  });

  app.get('/api/history/:id', (req, res) => {
    const history = readHistory();
    const run = history.find(r => r.id === req.params.id);
    if (!run) return res.status(404).json({ error: 'Not found' });
    res.json(run);
  });

  // ============ Agents ============

  app.get('/api/agents', (req, res) => {
    if (!fs.existsSync(agentsDir)) {
      return res.json([]);
    }
    try {
      const files = fs.readdirSync(agentsDir).filter(f => f.endsWith('.md'));
      const agents = files.map(f => {
        const content = fs.readFileSync(path.join(agentsDir, f), 'utf-8');
        const meta = parseFrontmatter(content);
        return {
          id: f.replace('.md', ''),
          filename: f,
          ...meta,
          content,
        };
      });
      res.json(agents);
    } catch (err) {
      res.status(500).json({ error: err.message });
    }
  });

  app.get('/api/agents/:name', (req, res) => {
    const filePath = path.join(agentsDir, `${req.params.name}.md`);
    if (!fs.existsSync(filePath)) {
      return res.status(404).json({ error: 'Agent not found' });
    }
    try {
      const content = fs.readFileSync(filePath, 'utf-8');
      const meta = parseFrontmatter(content);
      res.json({ id: req.params.name, ...meta, content });
    } catch (err) {
      res.status(500).json({ error: err.message });
    }
  });

  // ============ Patterns ============

  app.get('/api/patterns', (req, res) => {
    try {
      const { detect } = require('../../detector');
      const detected = detect(workspaceRoot);
      res.json(detected.codingPatterns || {});
    } catch (err) {
      res.status(500).json({ error: err.message });
    }
  });

  // ============ Runs ============

  app.post('/api/run', async (req, res) => {
    const { story, mode } = req.body;
    if (!story) return res.status(400).json({ error: 'Story is required' });
    try {
      const runId = await runManager.startRun(story, mode || 'interactive');
      res.json({ runId });
    } catch (err) {
      res.status(500).json({ error: err.message });
    }
  });

  app.delete('/api/run/:id', (req, res) => {
    runManager.stopRun(req.params.id);
    res.json({ success: true });
  });

  app.get('/api/runs/active', (req, res) => {
    res.json(runManager.getActiveRuns());
  });

  app.get('/api/runs', (req, res) => {
    res.json(runManager.getAllRuns());
  });

  app.get('/api/runs/:id', (req, res) => {
    const run = runManager.getRun(req.params.id);
    if (!run) return res.status(404).json({ error: 'Run not found' });
    res.json(run);
  });

  app.post('/api/runs/:id/message', async (req, res) => {
    const { message } = req.body;
    if (!message) return res.status(400).json({ error: 'Message is required' });
    try {
      await runManager.sendMessage(req.params.id, message);
      res.json({ success: true });
    } catch (err) {
      res.status(500).json({ error: err.message });
    }
  });

  // ============ Stats ============

  app.get('/api/stats', (req, res) => {
    const history = readHistory();

    const totalRuns = history.length;
    const successRuns = history.filter(r => r.outcome === 'success').length;
    const totalCost = history.reduce((sum, r) => {
      const cost = parseFloat((r.estimatedCost || '').replace('$', '')) || 0;
      return sum + cost;
    }, 0);
    const avgDuration = history.length > 0
      ? history.reduce((sum, r) => {
          if (r.startedAt && r.completedAt) {
            return sum + (new Date(r.completedAt) - new Date(r.startedAt));
          }
          return sum;
        }, 0) / history.length / 1000 / 60 // minutes
      : 0;

    res.json({
      totalRuns,
      successRate: totalRuns > 0 ? Math.round((successRuns / totalRuns) * 100) : 0,
      totalCost: totalCost.toFixed(2),
      avgDuration: avgDuration.toFixed(1),
    });
  });
}

function parseFrontmatter(content) {
  const match = content.match(/^---\n([\s\S]*?)\n---/);
  if (!match) return {};
  const meta = {};
  const lines = match[1].split('\n');
  for (const line of lines) {
    const [key, ...rest] = line.split(':');
    if (key && rest.length > 0) {
      let value = rest.join(':').trim();
      // Remove quotes
      if (value.startsWith('"') && value.endsWith('"')) value = value.slice(1, -1);
      meta[key.trim()] = value;
    }
  }
  return meta;
}

